        /// <summary>
        /// For inline array types, custom indexers, 'Slice' methods and conversion operators to
        /// <see cref="System.Span{T}"/>/<see cref="System.ReadOnlySpan{T}"/> are bypassed in favor of the
        /// built-in element access and span conversions. Warn so developers are aware such members are ignored.
        /// </summary>
        private void CheckForUnusedInlineArrayMembers(BindingDiagnosticBag diagnostics)
        {
            if (TypeKind != TypeKind.Struct || !HasInlineArrayAttribute(out _))
            {
                return;
            }

            var compilation = DeclaringCompilation;
            TypeSymbol elementType = TryGetInlineArrayElementField()?.Type;

            foreach (var member in GetMembers())
            {
                switch (member)
                {
                    case PropertySymbol { IsIndexer: true } indexer:
                        if (!indexer.IsExplicitInterfaceImplementation
                            && !IsRefLikeType
                            && indexer.ParameterCount == 1
                            && IsInlineArrayIndexerParameterType(indexer.Parameters[0].Type, compilation))
                        {
                            diagnostics.Add(ErrorCode.WRN_InlineArrayIndexerNotUsed, indexer.GetFirstLocation());
                        }
                        break;

                    case MethodSymbol { MethodKind: MethodKind.Ordinary, Name: "Slice" } slice:
                        if (!slice.IsExplicitInterfaceImplementation
                            && slice.ParameterCount == 2
                            && slice.Parameters[0].Type.SpecialType == SpecialType.System_Int32
                            && slice.Parameters[1].Type.SpecialType == SpecialType.System_Int32
                            && !slice.ReturnsVoid)
                        {
                            diagnostics.Add(ErrorCode.WRN_InlineArraySliceNotUsed, slice.GetFirstLocation());
                        }
                        break;

                    case MethodSymbol { MethodKind: MethodKind.Conversion } op:
                        if (elementType is not null
                            && op.ParameterCount == 1
                            && IsSpanOfElementType(op.ReturnType, elementType, compilation)
                            && op.Parameters[0].Type.Equals(this, TypeCompareKind.AllIgnoreOptions))
                        {
                            diagnostics.Add(ErrorCode.WRN_InlineArrayConversionOperatorNotUsed, GetConversionOperatorTypeLocation(op));
                        }
                        break;
                }
            }
        }

        private static bool IsInlineArrayIndexerParameterType(TypeSymbol type, CSharpCompilation compilation)
        {
            return type.SpecialType == SpecialType.System_Int32
                || TypeSymbol.Equals(type, compilation.GetWellKnownType(WellKnownType.System_Index), TypeCompareKind.ConsiderEverything)
                || TypeSymbol.Equals(type, compilation.GetWellKnownType(WellKnownType.System_Range), TypeCompareKind.ConsiderEverything);
        }

        private static bool IsSpanOfElementType(TypeSymbol type, TypeSymbol elementType, CSharpCompilation compilation)
        {
            if (type is not NamedTypeSymbol { IsGenericType: true } namedType)
            {
                return false;
            }

            NamedTypeSymbol definition = namedType.OriginalDefinition;
            if (!TypeSymbol.Equals(definition, compilation.GetWellKnownType(WellKnownType.System_Span_T), TypeCompareKind.ConsiderEverything)
                && !TypeSymbol.Equals(definition, compilation.GetWellKnownType(WellKnownType.System_ReadOnlySpan_T), TypeCompareKind.ConsiderEverything))
            {
                return false;
            }

            return namedType.TypeArgumentsWithAnnotationsNoUseSiteDiagnostics[0].Type.Equals(elementType, TypeCompareKind.AllIgnoreOptions);
        }

        private Location GetConversionOperatorTypeLocation(MethodSymbol op)
        {
            foreach (var reference in op.DeclaringSyntaxReferences)
            {
                if (reference.GetSyntax() is ConversionOperatorDeclarationSyntax { Type: { } typeSyntax })
                {
                    return typeSyntax.Location;
                }
            }

            return op.GetFirstLocation();
        }
    }
